private val Void=Color(0xFF050816); private val Panel=Color(0xFF0A1024); private val Cyan=Color(0xFF55F7FF); private val Violet=Color(0xFF9B6BFF); private val Pink=Color(0xFFFF4FA3); private val Lime=Color(0xFFB9FF66); private val Muted=Color(0xFF7180A5)
private data class Node(val sector:Int,val color:Color)
private enum class GameMode{RUSH,ZEN}
private const val SECTORS=8; private const val RINGS=4; private const val SECTOR_ANGLE=360f/SECTORS

@Composable fun LoopshiftApp(){var mode by remember{mutableStateOf<GameMode?>(null)}; MaterialTheme(colorScheme=darkColorScheme(primary=Cyan,secondary=Violet,tertiary=Pink,background=Void,surface=Panel,onBackground=Color.White,onSurface=Color.White)){Surface(Modifier.fillMaxSize(),color=Void){when(mode){GameMode.RUSH->LoopshiftGame(GameMode.RUSH){mode=null};GameMode.ZEN->LoopshiftGame(GameMode.ZEN){mode=null};null->StartScreen({mode=GameMode.RUSH},{mode=GameMode.ZEN})}}}}

@Composable private fun StartScreen(onRush:()->Unit,onZen:()->Unit){val c=LocalContext.current;val p=remember{c.getSharedPreferences("loopshift",Context.MODE_PRIVATE)};val best=p.getInt("best",0);Column(Modifier.fillMaxSize().statusBarsPadding().navigationBarsPadding().padding(24.dp,18.dp),horizontalAlignment=Alignment.CenterHorizontally){Spacer(Modifier.weight(.45f));Logo();Text("LOOPSHIFT",fontWeight=FontWeight.Black,fontSize=34.sp,letterSpacing=5.sp);Text("FIND THE PATH. HOLD THE FLOW.",color=Muted,fontSize=10.sp,letterSpacing=2.sp);Spacer(Modifier.height(24.dp));Card(colors=CardDefaults.cardColors(containerColor=Panel),shape=RoundedCornerShape(22.dp),modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(20.dp)){Row(Modifier.fillMaxWidth()){Column(Modifier.weight(1f)){Text("RUSH",fontWeight=FontWeight.Black,fontSize=22.sp);Text("Starts easy. Builds into chaos.",color=Muted,fontSize=12.sp)};Text("BEST $best",color=Cyan,fontWeight=FontWeight.Bold,fontSize=12.sp)};Spacer(Modifier.height(16.dp));Button(onRush,Modifier.fillMaxWidth().height(50.dp)){Text("START RUSH",fontWeight=FontWeight.Black)}}};Spacer(Modifier.height(12.dp));Card(onClick=onZen,colors=CardDefaults.cardColors(containerColor=Panel.copy(.82f)),modifier=Modifier.fillMaxWidth()){Row(Modifier.padding(18.dp).fillMaxWidth()){Column(Modifier.weight(1f)){Text("ZEN",fontWeight=FontWeight.Black,fontSize=17.sp);Text("No timer. No lives. Just solve.",color=Muted,fontSize=11.sp)};Text("PLAY",color=Lime,fontWeight=FontWeight.Black)}};Spacer(Modifier.height(12.dp));Text("Difficulty now ramps from 2 → 3 → 4 rings",color=Muted,fontSize=11.sp);Spacer(Modifier.weight(1f));Text("KARTIK LABS  •  v0.6",color=Muted,fontSize=9.sp)}}

@Composable private fun Logo(){val t=rememberInfiniteTransition(label="logo");val spin by t.animateFloat(0f,360f,infiniteRepeatable(tween(9000,easing=LinearEasing)),label="spin");Canvas(Modifier.size(138.dp)){val s=size.minDimension*.045f;listOf(.42f,.31f,.20f).forEachIndexed{i,f->val r=size.minDimension*f;drawArc(listOf(Cyan,Violet,Pink)[i],-78f+i*22f+if(i==0)spin else -spin*.4f,292f,false,Offset(center.x-r,center.y-r),Size(r*2,r*2),style=Stroke(s,cap=StrokeCap.Round))};drawCircle(Color.White,s*.65f,center)}}

@Composable private fun LoopshiftGame(mode:GameMode,onExit:()->Unit){val context=LocalContext.current;val prefs=remember{context.getSharedPreferences("loopshift",Context.MODE_PRIVATE)};val zen=mode==GameMode.ZEN;var steps by remember{mutableStateOf(List(RINGS){Random.nextInt(SECTORS)})};var node by remember{mutableStateOf(randomNode())};var score by remember{mutableIntStateOf(0)};var combo by remember{mutableIntStateOf(0)};var lives by remember{mutableIntStateOf(3)};var paused by remember{mutableStateOf(false)};var over by remember{mutableStateOf(false)};var best by remember{mutableIntStateOf(prefs.getInt("best",0))};var reverse by remember{mutableIntStateOf(-1)};var feedback by remember{mutableIntStateOf(0)};var tutorial by remember{mutableStateOf(!zen&&!prefs.getBoolean("tutorial_seen",false))};var page by remember{mutableIntStateOf(0)};val activeRings=if(zen)4 else when{score<500->2;score<1500->3;else->4};var ringIndex by remember{mutableIntStateOf(activeRings-1)};val tickMs=when{zen->Long.MAX_VALUE;score<500->3200L;score<1500->2700L;score<3000->2200L;else->max(1100L,2200L-((score-3000)/500)*100L)};val pulse=remember{Animatable(1f)};fun sector(s:Int)=((s%SECTORS)+SECTORS)%SECTORS;fun haptic(strong:Boolean=false){val v=context.getSystemService(Vibrator::class.java)?:return;if(Build.VERSION.SDK_INT>=26)v.vibrate(VibrationEffect.createOneShot(if(strong)40 else 14,if(strong)140 else 60))};fun hazard()=if(!zen&&score>=3000&&Random.nextFloat()<.22f)Random.nextInt(activeRings) else -1;fun friendlySteps(count:Int)=List(RINGS){i->if(i<count)node.sector+Random.nextInt(-2,3) else Random.nextInt(SECTORS)};fun reset(){node=randomNode();steps=List(RINGS){Random.nextInt(SECTORS)};score=0;combo=0;lives=3;ringIndex=1;reverse=-1;over=false;paused=false};LaunchedEffect(feedback){if(feedback!=0){delay(180);feedback=0}};LaunchedEffect(paused,over,node,ringIndex,tutorial,activeRings){if(paused||over||tutorial)return@LaunchedEffect;if(zen){pulse.snapTo(1f);return@LaunchedEffect};pulse.snapTo(1f);pulse.animateTo(0f,tween(tickMs.toInt(),easing=LinearEasing));if(sector(steps[ringIndex])==node.sector){feedback=1;if(ringIndex==0){combo++;score+=100+(if(combo>=5)combo*20 else combo*10);if(score>best){best=score;prefs.edit().putInt("best",best).apply()};haptic(combo>=5);node=randomNode();ringIndex=(if(score<500)2 else if(score<1500)3 else 4)-1;reverse=hazard()}else{ringIndex--;haptic()}}else{feedback=-1;lives--;combo=0;haptic(true);if(lives<=0)over=true else{node=randomNode();ringIndex=activeRings-1;reverse=hazard()}}};LaunchedEffect(activeRings){if(ringIndex>=activeRings)ringIndex=activeRings-1};Column(Modifier.fillMaxSize().statusBarsPadding().navigationBarsPadding().padding(20.dp,12.dp),horizontalAlignment=Alignment.CenterHorizontally){Header(mode,score,best,lives,combo,paused,onExit){paused=!paused};Spacer(Modifier.height(8.dp));Text(if(zen)"NO TIMER" else "$activeRings RINGS  •  ${tickMs/1000f}s",color=if(zen)Lime else Cyan,fontWeight=FontWeight.Bold,fontSize=11.sp);if(reverse>=0)Text("REVERSE RING ACTIVE",color=Pink,fontSize=10.sp,fontWeight=FontWeight.Black);Box(Modifier.fillMaxWidth().weight(1f),contentAlignment=Alignment.Center){GameBoard(steps,node,ringIndex,activeRings,combo,if(zen)1f else pulse.value,reverse,feedback,!paused&&!over&&!tutorial){tap->if(tap<activeRings){steps=steps.toMutableList().also{it[tap]+=if(tap==reverse)-1 else 1};haptic()}};if(tutorial)TutorialCard(page,{if(page<2)page++ else{tutorial=false;prefs.edit().putBoolean("tutorial_seen",true).apply()}},{tutorial=false;prefs.edit().putBoolean("tutorial_seen",true).apply()}) else if(paused&&!over)OverlayCard("PAUSED","Take your time"){paused=false} else if(over)OverlayCard("FLOW BROKEN","Score $score  •  Best $best","SHIFT AGAIN"){reset()}};AnimatedVisibility(combo>=5&&!over){Text("FLOW ×$combo",color=Lime,fontWeight=FontWeight.Black,fontSize=20.sp)};Text(if(zen)"ZEN • Tap until each gate aligns. There is no countdown." else when(activeRings){2->"WARM UP • Only 2 rings. Learn the rhythm.";3->"NICE • Third ring unlocked.";else->"FULL SHIFT • All four rings active."},color=Muted,textAlign=TextAlign.Center,fontSize=12.sp);Spacer(Modifier.height(8.dp))}}

@Composable private fun Header(mode:GameMode,score:Int,best:Int,lives:Int,combo:Int,paused:Boolean,onExit:()->Unit,onPause:()->Unit){Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("LOOPSHIFT",fontWeight=FontWeight.Black,fontSize=22.sp,letterSpacing=3.sp);Text(if(mode==GameMode.ZEN)"ZEN MODE" else "RUSH MODE",color=Muted,fontSize=9.sp)};TextButton(onClick=onExit){Text("HOME",color=Muted)};FilledTonalButton(onClick=onPause){Text(if(paused)"RESUME" else "PAUSE",fontSize=10.sp)}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Stat("SCORE","$score",Modifier.weight(1f));if(mode==GameMode.RUSH)Stat("BEST","$best",Modifier.weight(1f));Stat("FLOW","×$combo",Modifier.weight(1f));Stat(if(mode==GameMode.ZEN)"MODE" else "LIVES",if(mode==GameMode.ZEN)"∞" else "●".repeat(lives),Modifier.weight(1f),if(mode==GameMode.ZEN)Lime else Pink)}}
@Composable private fun Stat(l:String,v:String,m:Modifier,c:Color=Color.White){Column(m.background(Panel,RoundedCornerShape(14.dp)).padding(9.dp),horizontalAlignment=Alignment.CenterHorizontally){Text(l,color=Muted,fontSize=8.sp);Text(v,color=c,fontWeight=FontWeight.Bold,fontSize=15.sp)}}

@Composable private fun GameBoard(steps:List<Int>,node:Node,ringIndex:Int,activeRings:Int,combo:Int,pulse:Float,reverse:Int,feedback:Int,enabled:Boolean,onTap:(Int)->Unit){val animated=steps.mapIndexed{i,s->animateFloatAsState(s.toFloat(),spring(stiffness=Spring.StiffnessMediumLow),label="r$i").value};Canvas(Modifier.aspectRatio(1f).fillMaxWidth().pointerInput(enabled){if(enabled)detectTapGestures{tap->val c=Offset(size.width/2f,size.height/2f);val d=(tap-c).getDistance();val mr=minOf(size.width,size.height)*.45f;val r=(d/(mr/RINGS)).toInt();if(r in 0 until activeRings)onTap(r)}}){val c=center;val mr=size.minDimension*.45f;val space=mr/RINGS;val stroke=size.minDimension*.018f;val sweep=360f/SECTORS;if(feedback!=0)drawCircle((if(feedback>0)Lime else Pink).copy(.14f),mr*1.13f,c);if(pulse<1f){val tr=mr*1.07f;drawArc(if(pulse<.28f)Pink else Cyan,-90f,360f*pulse,false,Offset(c.x-tr,c.y-tr),Size(tr*2,tr*2),style=Stroke(stroke*.65f,cap=StrokeCap.Round))};repeat(RINGS){i->val radius=space*(i+1);val active=i<activeRings;val color=when{i==reverse->Pink;i==ringIndex->Cyan;active->Violet;else->Muted.copy(.18f)};drawCircle(Color(0xFF1A2443),radius,c,style=Stroke(stroke));if(active){val gateAngle=animated[i]*SECTOR_ANGLE;for(sec in 0 until SECTORS){val centerAngle=sec*sweep+gateAngle;drawArc(color.copy(if(i==ringIndex||i==reverse).95f else .58f),centerAngle-90f+12f,sweep-24f,false,Offset(c.x-radius,c.y-radius),Size(radius*2,radius*2),style=Stroke(stroke,cap=StrokeCap.Round))};val ga=Math.toRadians((gateAngle-90f).toDouble());drawCircle(color,stroke*.6f,Offset(c.x+cos(ga).toFloat()*radius,c.y+sin(ga).toFloat()*radius))}};val ar=space*(ringIndex+1);val a=Math.toRadians((node.sector*sweep-90f).toDouble());val np=Offset(c.x+cos(a).toFloat()*ar,c.y+sin(a).toFloat()*ar);drawCircle(node.color.copy(.25f),stroke*2.5f,np);drawCircle(node.color,stroke*.8f,np);drawCircle(Color(0xFF101A33),space*.48f,c);drawCircle(Color.White,stroke*.35f,c)}}

@Composable private fun TutorialCard(page:Int,onNext:()->Unit,onSkip:()->Unit){val title=listOf("ROUTE THE PULSE","TAKE YOUR TIME","DIFFICULTY GROWS")[page];val text=listOf("Tap a ring until its glowing gate lines up with the energy node.","Rush now starts with over 3 seconds and only two rings.","More rings and reverse hazards unlock only after you build confidence.")[page];Card(colors=CardDefaults.cardColors(containerColor=Panel.copy(.98f)),modifier=Modifier.padding(26.dp).fillMaxWidth()){Column(Modifier.padding(22.dp),horizontalAlignment=Alignment.CenterHorizontally){Text("${page+1} / 3",color=Muted);Text(title,fontWeight=FontWeight.Black,fontSize=21.sp);Spacer(Modifier.height(10.dp));Text(text,color=Color.White.copy(.86f),textAlign=TextAlign.Center);Spacer(Modifier.height(18.dp));Button(onNext,Modifier.fillMaxWidth()){Text(if(page==2)"START" else "NEXT")};TextButton(onClick=onSkip){Text("SKIP",color=Muted)}}}}
@Composable private fun OverlayCard(title:String,subtitle:String,button:String="RESUME",onAction:()->Unit){Card(colors=CardDefaults.cardColors(containerColor=Panel.copy(.96f)),modifier=Modifier.padding(34.dp).fillMaxWidth()){Column(Modifier.padding(24.dp),horizontalAlignment=Alignment.CenterHorizontally){Text(title,fontWeight=FontWeight.Black,fontSize=24.sp);Text(subtitle,color=Muted);Spacer(Modifier.height(18.dp));Button(onAction,Modifier.fillMaxWidth()){Text(button,fontWeight=FontWeight.Black)}}}}
private fun randomNode():Node=Node(Random.nextInt(SECTORS),listOf(Cyan,Pink,Lime,Violet).random())
